import json, sys, yaml

data = json.load(sys.stdin)
result_yaml = data['result']
registry = yaml.safe_load(result_yaml)
exps = registry['data']['experiments']

# Comprehensive summary table for all 111 experiments
print('| # | exp_id | status | conclusion | updated_at | key_metrics |')
print('|---|--------|--------|-----------|------------|-------------|')
for i, (exp_id, exp) in enumerate(sorted(exps.items()), 1):
    status = exp.get('status', '?')
    conclusion = exp.get('conclusion', '-')
    updated = exp.get('updated_at', '-')
    metrics = exp.get('metrics', {})

    metric_summary = ''
    if isinstance(metrics, dict):
        # Extract the most relevant metrics
        if 'train_loss' in metrics:
            metric_summary += f'loss={metrics[\"train_loss\"]}'
        if 'mean_token_accuracy' in metrics:
            metric_summary += f' acc={metrics[\"mean_token_accuracy\"]}'
        if 'mmlu' in metrics:
            metric_summary += f' mmlu={metrics[\"mmlu\"]}'
        if 'gsm8k' in metrics:
            metric_summary += f' gsm8k={metrics[\"gsm8k\"]}'
        if 'gamma' in metrics:
            metric_summary += f' gamma={metrics[\"gamma\"]}'
        if 'joint_gamma' in metrics:
            metric_summary += f' j_gamma={metrics[\"joint_gamma\"]}'
        if 'gamma_perbench' in metrics:
            metric_summary += f' pb_gamma={metrics[\"gamma_perbench\"]}'
        if 'gamma_joint' in metrics:
            metric_summary += f' j_gamma={metrics[\"gamma_joint\"]}'
        if 'runs_completed' in metrics:
            metric_summary += f' runs={metrics[\"runs_completed\"]}'
        if 'INVALID' in metrics:
            metric_summary = 'INVALID'
        if not metric_summary and metrics:
            keys = list(metrics.keys())[:3]
            metric_summary = str(keys)

    if not metric_summary:
        metric_summary = '-'

    print(f'| {i} | {exp_id} | {status} | {conclusion} | {updated[:16] if updated != \"-\" else \"-\"} | {metric_summary.strip()} |')
